<template><view class="phone orders-page"><PageHeader title="充电订单" back/><ConnectionState/><view class="filter-tabs"><button v-for="f in filters" :key="f.key" :class="{active:filter===f.key}" @click="filter=f.key">{{f.label}}</button></view><view class="padded-content"><view class="panel"><input v-model="search" class="form-input" placeholder="搜索站点、插座或订单号" aria-label="订单搜索"/><view class="section-row"><picker mode="date" :value="fromDate" @change="fromDate=$event.detail.value"><text>开始：{{fromDate||'不限'}}</text></picker><picker mode="date" :value="toDate" @change="toDate=$event.detail.value"><text>结束：{{toDate||'不限'}}</text></picker><button class="small-link" @click="fromDate='';toDate='';search=''">清空</button></view></view><view v-for="o in orders" :key="o.id" class="panel order-card" @click="go('/pages/session/index?id='+o.id)"><view class="section-row"><text class="section-title">{{isBackend?'充电订单':'电单车充电'}}</text><text :class="o.status==='charging'?'teal':'muted'">{{orderStatusText(o)}} ›</text></view><view class="order-station">{{o.stationName}}</view><view class="muted small">插座 {{o.socketCode}}</view><view class="order-stats"><text>{{o.minutes===null?'—':o.minutes}} 分钟</text><text>{{energy(o.energyWh)}} 度</text><text class="order-price">¥{{yuan(o.totalCents)}}</text></view></view><view v-if="!orders.length" class="empty-state">暂无相关订单<text>{{isBackend?'可刷新查看最新订单':'开始一笔模拟充电即可体验'}}</text></view><DemoNotice/></view></view></template>
<script setup>
import {ref,computed} from 'vue';import {onShow} from '@dcloudio/uni-app';import ConnectionState from '../../components/ConnectionState.vue';import {orderStatusText,matchesOrderFilter} from '../../domain/order-status.mjs';import PageHeader from '../../components/PageHeader.vue';import DemoNotice from '../../components/DemoNotice.vue';import {state,go,isBackend,refreshData} from '../../store.js';import {yuan,energy} from '../../domain/charging.mjs';
const filters=[{key:'all',label:'全部'},{key:'charging',label:'充电中'},{key:'unpaid',label:'待支付'},{key:'ended',label:'已完成'},{key:'failed',label:'启动失败'}],filter=ref('all');
const search=ref(''),fromDate=ref(''),toDate=ref('');const day=t=>{if(!Number.isFinite(t))return '';const d=new Date(t);return [d.getFullYear(),String(d.getMonth()+1).padStart(2,'0'),String(d.getDate()).padStart(2,'0')].join('-');};
const orders=computed(()=>state.orders.filter(o=>matchesOrderFilter(o,filter.value)&&(!search.value||(o.stationName+' '+o.socketCode+' '+(o.orderNo||o.id)).includes(search.value.trim()))&&(!fromDate.value||day(o.startedAt)>=fromDate.value)&&(!toDate.value||day(o.startedAt)<=toDate.value)));
onShow(()=>refreshData());
</script>
